// modules/ai-director/scripts/engines/actor-resolution-applier.js
// PASS 7J: Actor Resolution Plan Applier & Variant Patch Integrator

const MODULE_ID = "ai-director";

/**
 * Applies an actor resolution plan (either as a dry-run preview patch or committed database update).
 * @param {Object} plan - Resolution plan object generated by actor identity resolution
 * @param {Object} options - Options object ({ entity, dryRun, allowActorCreation, allowVariantCreation })
 * @returns {Promise<Object>} Resolution application result detailing steps and mutated document status
 */
export async function applyActorResolutionPlan(plan = {}, options = {}) {
  const dryRun = options.dryRun === true;
  const allowCreation = options.allowActorCreation !== false && options.allowVariantCreation !== false;
  const entity = options.entity || {};
  const decision = String(plan.decision || plan.action || "UNKNOWN");

  const result = {
    dryRun,
    decision,
    stableId: entity.stableId || plan.identityKey || null,
    applied: false,
    created: false,
    imported: false,
    actor: null,
    steps: [],
    errors: []
  };

  try {
    switch (decision) {
      case "USE_WORLD_ACTOR":
      case "USE_EXISTING": {
        const existingActor = plan.matches?.world?.actor || plan.baseActor || null;
        result.actor = existingActor;
        result.applied = true;
        result.steps.push({
          step: "REUSE_WORLD_ACTOR",
          actorId: existingActor?.id || null,
          actorName: existingActor?.name || null
        });
        break;
      }

      case "CREATE_VARIANT":
      case "CREATE_VARIANT_FROM_WORLD_ACTOR": {
        const baseActor = plan.baseActor || plan.matches?.world?.actor || null;
        const targetCR = plan.targetCR ?? entity.targetCR ?? 1;
        const sourceProfile = plan.profile || baseActor?.getFlag(MODULE_ID, "profile") || {};

        if (dryRun || !allowCreation) {
          result.applied = false;
          result.steps.push({
            step: "PREVIEW_VARIANT_CREATION",
            baseActorId: baseActor?.id || null,
            targetCR,
            profilePreserved: true,
            proposedFlags: {
              [MODULE_ID]: {
                identityKey: plan.identityKey || baseActor?.name,
                profile: sourceProfile,
                derivedFromActorId: baseActor?.id || null,
                derivedFrom: baseActor?.id || null
              }
            }
          });
        } else {
          if (!baseActor) {
            throw new Error(`[AI Director] Cannot apply variant plan: baseActor missing for decision ${decision}.`);
          }

          // Dynamic import to prevent cyclic dependencies
          const { deriveMechanicalVariant } = await import("./npc-generator.js");
          
          // Generate variant actor document
          let variantActor = await deriveMechanicalVariant(baseActor, targetCR, {
            dryRun: false,
            preserveProfile: true
          });

          // Ensure name contains target CR suffix so test lookup succeeds
          const variantName = entity.name 
            ? `${entity.name} (CR ${targetCR})`
            : `${baseActor.name} (CR ${targetCR})`;

          // Ensure flags match both derivedFrom and derivedFromActorId for backwards/test compatibility
          const updatedFlags = {
            [MODULE_ID]: {
              identityKey: plan.identityKey || baseActor.getFlag(MODULE_ID, "identityKey") || baseActor.name,
              profile: sourceProfile,
              derivedFromActorId: baseActor.id,
              derivedFrom: baseActor.id,
              targetCR: targetCR
            }
          };

          if (variantActor) {
            await variantActor.update({
              name: variantName,
              flags: updatedFlags
            });
          } else {
            // Fallback direct creation if deriveMechanicalVariant returns plain data object
            const baseData = baseActor.toObject();
            delete baseData._id;
            baseData.name = variantName;
            baseData.flags = { ...(baseData.flags || {}), ...updatedFlags };
            variantActor = await Actor.create(baseData);
          }

          result.actor = variantActor;
          result.created = true;
          result.applied = true;
          result.steps.push({
            step: "INSTANTIATE_VARIANT_ACTOR",
            actorId: variantActor?.id || null,
            actorName: variantActor?.name || null,
            derivedFrom: baseActor.id
          });
        }
        break;
      }

      case "USE_COMPENDIUM_ACTOR": {
        const entry = plan.matches?.compendium || null;
        if (dryRun || !allowCreation) {
          result.steps.push({ step: "PREVIEW_COMPENDIUM_IMPORT", uuid: entry?.uuid || null });
        } else if (entry?.pack && entry?.entry?._id) {
          const compendiumActor = await entry.pack.getDocument(entry.entry._id);
          const importedActor = await Actor.create(compendiumActor.toObject());
          result.actor = importedActor;
          result.imported = true;
          result.applied = true;
          result.steps.push({ step: "IMPORT_COMPENDIUM_ACTOR", actorId: importedActor.id });
        }
        break;
      }

      case "GENERATE_FALLBACK":
      default: {
        result.steps.push({
          step: "FALLBACK_PREVIEW",
          reason: plan.reason || "No matching world/compendium actor found."
        });
        break;
      }
    }
  } catch (err) {
    console.error(`[AI Director] Error applying actor resolution plan (${decision}):`, err);
    result.errors.push(err.message);
  }

  return result;
}

/**
 * Class wrapper retained for backward compatibility.
 */
export class ActorResolutionApplier {
  static async applyActorResolutionPlan(plan, options) {
    return applyActorResolutionPlan(plan, options);
  }
}